import { HttpClient } from '@angular/common/http';
import { Injectable, computed, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';

interface SheetView {
  id: string;
  today: string;
  floor: string;
  terms: number;
  latePct: string;
  policyDate: string | null;
  cap: string | null;
  dated: Dated;
  archived: boolean;
  lastBatch: number | null;
}

/** A value recorded for a dated setting from a date (yyyy-mm-dd) on; null when none. */
export interface DatedValue {
  from: string;
  value: string | null;
}

/** The values recorded for each dated setting (floor, late-pct, terms, terms-<grade>, grace-<grade>, clerk-limit, cap,
 * proof-threshold, proof-threshold-<grade>, note-threshold), by key. */
export type Dated = Partial<Record<string, DatedValue[]>>;

/** The values in force before any is recorded: a key without one has none. */
const STARTING: Partial<Record<string, string>> = { floor: '1.00', 'late-pct': '0.00', terms: '14' };

/**
 * What a claim's late charge and rounding depend on: the sheet's late percent in force on a date, its today, and
 * the policy date in force (the sheet's today when blank), before which a claim's live figures round half up.
 */
export interface Late {
  pctOn: (date: string) => string;
  today: string | null;
  policy: string | null;
}

/** A claim template on the sheet: a claim made from it takes its amount (two decimals) and note then. */
export interface ClaimTemplate {
  id: number;
  name: string;
  amount: string;
  note: string;
}

/** A person on the sheet as other sections need them: who they are and whether they are retired. */
export interface PersonRef {
  id: number;
  name: string;
  retired: boolean;
}

// The signed-in user and the active sheet. Every other feature reads these to scope its calls.
@Injectable({ providedIn: 'root' })
export class Session {
  private readonly http = inject(HttpClient);

   * figure is shown as it stood at the end of that date, with it as the sheet's today, and every change
   * is refused. It belongs to this screen, and is left as it is by loading a sheet.
   */
  readonly asOf = signal<string | null>(null);
  /** Whether retired people are listed: off when the screen opens, left as it is by loading a sheet. */
  readonly showRetired = signal(false);

  async signIn(name: string): Promise<void> {
    const res = await firstValueFrom(this.http.post<{ name: string }>('/api/session', { name }));
    this.user.set(res.name);
  }

  async loadSheet(id: string): Promise<void> {
    const user = this.user();
    if (!user) throw new Error('not signed in');
    const res = await firstValueFrom(
      this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/load`, null, {
        headers: { 'X-User': user },
      }),
    );
    this.sheetId.set(res.id);
    this.today.set(res.today);
    this.dated.set(res.dated);
    this.policyDate.set(res.policyDate);
    this.archived.set(res.archived);
    this.lastBatch.set(res.lastBatch);
    this.loads.update((n) => n + 1);
  }

  /** View the active sheet as of a date (yyyy-mm-dd), or as it is now (null): it is loaded again. */
  async setAsOf(asOf: string | null): Promise<void> {
    const id = this.sheetId();
    if (!id) throw new Error('no sheet loaded');
    this.asOf.set(asOf);
    await this.loadSheet(id);
  }

  async setToday(today: string): Promise<void> {
    const user = this.user();
    const id = this.sheetId();
    if (!user || !id) throw new Error('no sheet loaded');
    const res = await firstValueFrom(
      this.http.put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/today`, { today }, {
        headers: { 'X-User': user },
      }),
    );
    if (this.sheetId() === res.id) this.today.set(res.today);
  }

  async archive(): Promise<void> {
    const user = this.user();
    const id = this.sheetId();
    if (!user || !id) throw new Error('no sheet loaded');
    const res = await firstValueFrom(
      this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/archive`, null, {
        headers: { 'X-User': user },
      }),
    );
    if (this.sheetId() === res.id) this.archived.set(res.archived);
  }
}
package net.officefloor.hq.app.asof;


/**
 * The as-of view, which belongs to the user's screen: a request to a sheet carrying an
 * {@value #HEADER} date is shown as the sheet stood at the end of that date, and a change asked
 * with one is refused before anything is written. Every other change made to a sheet that has gone
 * through is marked for {@link SheetHistoryFilter} to record in its {@link SheetHistory}.
 *
 * <p>A read as of a date runs in a transaction that puts the sheet back as it stood then, with that
 * date as its today, and is rolled back once the read is answered, so it changes nothing and audits
 * nothing.
 */
@Configuration
public class AsOfGuard implements WebMvcConfigurer, HandlerInterceptor {

    /** The request header carrying the user's as-of date (yyyy-mm-dd). */
    public static final String HEADER = "X-As-Of";

    private static final String VIEW = AsOfGuard.class.getName() + ".view";

    /** A read as of a date under way: its transaction and the lock it holds on its sheet. */
    private record View(TransactionStatus transaction, ReentrantLock lock) {}

    private final SheetHistory history;
    private final PlatformTransactionManager transactions;
    /** One as-of read of a sheet at a time: each puts back the same rows. */
    private final Map<String, ReentrantLock> locks = new ConcurrentHashMap<>();

    public AsOfGuard(SheetHistory history, PlatformTransactionManager transactions) {
        this.history = history;
        this.transactions = transactions;
    }

    @Override
    public void addInterceptors(InterceptorRegistry registry) {
        registry.addInterceptor(this).addPathPatterns("/api/sheets/*/**");
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        if (!(handler instanceof HandlerMethod method)) return true;
        String sheetId = sheetId(request);
        String header = request.getHeader(HEADER);
        if (sheetId == null || header == null || header.isBlank()) return true;
        if (!isRead(request) && !method.hasMethodAnnotation(AsOfRead.class)) throw new AsOfRefusedException();
        LocalDate asOf;
        try {
            asOf = LocalDate.parse(header.trim());
        } catch (DateTimeParseException e) {
            throw new AsOfRefusedException();
        }
        // a sheet never started is started as usual
        if (!history.exists(sheetId)) return true;
        ReentrantLock lock = locks.computeIfAbsent(sheetId, id -> new ReentrantLock());
        lock.lock();
        TransactionStatus transaction = null;
        try {
            transaction = transactions.getTransaction(new DefaultTransactionDefinition());
            history.restore(sheetId, asOf);
        } catch (RuntimeException e) {
            if (transaction != null) transactions.rollback(transaction);
            lock.unlock();
            throw e;
        }
        request.setAttribute(VIEW, new View(transaction, lock));
        return true;
    }

    @Override
    public void afterCompletion(HttpServletRequest request, HttpServletResponse response, Object handler, Exception ex) {
        if (request.getAttribute(VIEW) instanceof View view) {
            request.removeAttribute(VIEW);
            try {
                transactions.rollback(view.transaction());
            } finally {
                view.lock().unlock();
            }
            return;
        }
        if (isRead(request) || ex != null || response.getStatus() >= 400) return;
        String sheetId = sheetId(request);
        if (sheetId != null) request.setAttribute(SheetHistoryFilter.CHANGED, sheetId);
    }

    private static boolean isRead(HttpServletRequest request) {
