      const id = this.session.sheetId();
      this.session.loads();
      this.periodNumberingFrom.set(null);
      this.graceDays.set(null);
      this.entryDate.set(null);
      this.pot.set(null);
      this.userRoles.set([]);
      this.permissionsSet.set({});
      this.error.set('');
      this.roleError.set('');
      this.delegations.set([]);
      this.delegateError.set('');
